CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,imei_cipher TEXT NOT NULL,imei_digest TEXT NOT NULL,brand TEXT DEFAULT '',model TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'protected' CHECK(status IN ('protected','lost','recovered','unlinked')),lost_mode BOOLEAN NOT NULL DEFAULT false,battery INTEGER,last_seen TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,imei_digest));
CREATE TABLE IF NOT EXISTS locations(id BIGSERIAL PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,latitude DOUBLE PRECISION NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude DOUBLE PRECISION NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy DOUBLE PRECISION NOT NULL DEFAULT 0,battery INTEGER,source TEXT NOT NULL DEFAULT 'android-app',recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS locations_device_time_idx ON locations(device_id,recorded_at DESC);
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,device_id UUID REFERENCES devices(id) ON DELETE CASCADE,kind TEXT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_events(id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());